#ifndef Q1_H
#define Q1_H
#include <cmath>
namespace q1 {
template <typename T = double, typename Func = T(*)(T)>
T gradient_descent(T x0, T lr, Func f = [](T a){return std::cos(a);}) {
    T x = x0;
    for (int i = 0; i < 100000; ++i) {
        T h = 1e-6;
        T grad = (f(x + h) - f(x - h)) / (2 * h);
        x = x - lr * grad;
    }
    return x;
}
}
#endif
