#ifndef Q2_H
#define Q2_H
#include <string>
#include <vector>
#include <fstream>
#include <sstream>
namespace q2 {
struct Patient {
    std::string name;
    int age;
    double weight;
    double height;
    std::string disease;
};
inline std::vector<Patient> read_file(const std::string& path) {
    std::vector<Patient> out;
    std::ifstream f(path);
    std::string line;
    std::getline(f, line);
    while (std::getline(f, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string tok;
        Patient p;
        std::getline(ss, p.name, ',');
        std::getline(ss, tok, ','); p.age = std::stoi(tok);
        std::getline(ss, tok, ','); p.weight = std::stod(tok);
        std::getline(ss, tok, ','); p.height = std::stod(tok);
        std::getline(ss, p.disease, ',');
        out.push_back(p);
    }
    return out;
}
}
#endif
EOF
